#include "media_pipeline.h"
#include <filesystem>
#include <fstream>
#include <iostream>
int main(){auto d=std::filesystem::temp_directory_path()/"msf_img_test";std::error_code ec;std::filesystem::remove_all(d,ec);std::filesystem::create_directories(d,ec);auto p=d/"t.pgm";{std::ofstream f(p,std::ios::binary);f<<"P5\n64 64\n255\n";for(int i=0;i<4096;i++)f.put((char)((i%64)<32?20:220));}msf::MediaPipeline x;std::uint64_t fp=0;if(!x.image(p.string(),fp)||fp==0)return 1;auto b=d/"t.bmp";{const int w=16,h=16,row=((w*3+3)/4)*4;std::ofstream f(b,std::ios::binary);unsigned char hd[54]={0};hd[0]='B';hd[1]='M';const int fs=54+row*h;hd[2]=(unsigned char)(fs&0xFF);hd[3]=(unsigned char)((fs>>8)&0xFF);hd[10]=54;hd[14]=40;hd[18]=(unsigned char)w;hd[22]=(unsigned char)h;hd[26]=1;hd[28]=24;f.write((const char*)hd,54);for(int y=0;y<h;++y){for(int xx=0;xx<w;++xx){f.put((char)30);f.put((char)40);f.put((char)220);}for(int k=w*3;k<row;++k)f.put(0);}}auto r=x.imageBatch({b.string()},true,256);if(r.size()!=1||!r[0].ok||!r[0].hasColorThumb||r[0].colorThumb.width<=0||r[0].colorThumb.height<=0||r[0].colorThumb.bgra.size()!=(std::size_t)r[0].colorThumb.width*r[0].colorThumb.height*4)return 2;std::cout<<"image_pipeline=ok\n";std::filesystem::remove_all(d,ec);return 0;}